"""changelog_data.py: アプリのバージョン番号と更新履歴データ。

画面の「VERx.y.z」バッジと更新履歴一覧(/api/changelog)の元データ。
意味のある変更をコミットするたびに APP_VERSION を上げ、CHANGELOG の
先頭へ新しいエントリを追記すること(新しい順)。

**利用者に見える変更が無い版は `'dev': True` を付ける**(§9.336、REVIEW 3-12)。
現場の人が開く「更新履歴」に、テストの名前や§番号や中のファイル名が並ぶのを
やめるため。画面は既定でこの版を伏せ、「開発の記録も出す」で出せる
(**消さない**——伏せるだけ・§4)。

- 付けるのは**構造の改善だけの版**(画面・サーバーの動きが1つも変わらない版)。
- **不具合を直した版には付けない**。中身が内部の話でも、直ったこと自体は
  利用者に見える変更(実際に VER2.206.0・VER2.214.0 は内部の話に見えるが
  「開けなくなる」「タブの中身が入れ替わる」を直した版)。
- **版そのものは上げ続ける**。「どのコードが動いているか」を版で見分ける
  仕掛け(§9.316 の起動の状況)が版に乗っているため、上げないと現場から
  更新が届いたかを確かめられなくなる。
- 判定を画面へ写さないこと。答えるのは下の `is_dev()` の1箇所(§9.163)。

**古い版(VER2.200.x 以前)には付けていない。** 430版を後から judgment で
分けると、内部の話に見える本物の不具合修正を伏せてしまう——付いていない=
利用者向け、という安全側にしてある。
"""
APP_VERSION='2.340.0'

# 更新履歴。画面の「VERx.y.z」バッジから一覧表示する。APP_VERSIONを
# 上げるたびに、このリストの先頭に新しいバージョンを追記すること。

def is_dev(entry):
    """その版が「開発の記録」か。**答えるのはここだけ**(§9.163)。

    宣言が無ければ利用者向け——伏せる側へ倒すと、宣言を忘れた版が
    黙って現場から消える。
    """
    return bool((entry or {}).get('dev'))


