  '——円周が食い違っている刃どうしなので、この配置では噛み合って切れません。'
  '中心どうしが**刃厚＋クリアランス**だけ離れる形に改めました。'
  '**条幅の出方は変わりません**（材料が切れる面は、公称の切断位置をはさんで'
