  'あわせて、端から端が有効長を超えていないことを機械で見張るようにしました'
  '（実測: 0〜1599.6mm ／ 有効長 1599.6mm）。',
  '**断面図の板のずれを、板厚1枚ぶんに直しました**（利用者のご指摘）。'
  '2枚ぶんずれており、条のあいだに板厚1枚ぶんの空きができていました。',
  '**スペーサー幅とゴムリング幅の字が混ざらないようにしました**（利用者のご指摘）。'
