  '自動で更新してほしい」）。予定の行が持っているのは**入れたときの写し**なので、'
  '出荷日のように**あとから決まる項目**は、入れたときの値のまま止まっていました。',
  'スケジュールを開いたときに、**画面に出している項目だけ**を'
