  '「元データが変わったとき」）。切り替えると、'
  '上に「3件に変更あり」と出て、**中身を見てから取り込む**形になります。'
  '設定は**この現場ぜんたいで1つ**で、再起動は要りません。',
  '書き換えるのは**編集できる端末だけ**です（閲覧の端末は見るだけ）。'
  '仕掛の側が空欄のときは**触りません**（読めなかったのか消したのかを'
