  '上下どちらの端でも送ります（行き過ぎても戻れます）。'
  '**離すと止まります。** 予定の行だけでなく、申し送り・枠・'
  '仕掛一覧からの持ち込みでも同じように送られます。',
  '**「表示」に「色と濃さの意味」を足しました**'
