  '**登録一覧からプリセットを作れるようにしました。**'
  '一覧は組み合わせごとの節に分かれ、条件を選んで名前を付けると'
  '1つのプリセットになります。節から**名前を変える／解く**もできます。'
  '**文字の見切れを直しました**——名前は折り返し、全部の行に同じ文字が'
  '並んでいた「DB / 表」の列は畳みました。',
  '**操業データ項目の「色」を13色＋既定へ増やしました。**'
  '呼び名は「未入力の色」と同じ言葉にそろえてあります'
