  '（1000pxの画面で877px→960px）。右の見本の紙も**A4の比**で大きく出ます。',
  '**マスタ管理に「帳票レイアウト」を足しました。**'
  '帳票画面の「配置を組み換え」は実質「設備ごとの紙のマスタ」だったので、'
