  '置き場所は「紙で組み換える」から、**見本のロットで実際の紙を見ながら**'
  '決められます（その設備で測ったロットがこの端末に無くても直せます）。',
  '**見本のロットが器の上限まで埋まりました。**'
  '**40条・9丈**、子ロット9件（異幅・子ロットごとの公差つき）、'
  '**保存済みの異常位置判定**（該当条つき）と異常情報、平面度・備考・'
  '丈別データまで入っています。**ロット№は7桁**（実機と同じ桁数）です。',
  '**帳票ブロックの「載せる項目」の候補を直しました。**'
  '「製造材質」「製造板厚」「製造板幅」が**実データでは必ず空**になる道を'
