  '**紙のどこに、どんな大きさで出るかが見えるようになりました。**'
  '右の見本は**A4と同じ縦横比の紙に12マスの格子**を敷いたもので、'
  '幅・高さを押すとその場で塊の位置と大きさが変わります。'
  '「6マス」が紙の何割かを頭の中で計算する必要はありません'
