  '入切・間隔・残す世代・残す日数は同じ画面で変えられ、保存後すぐ反映されます。',
  '**消す前に、何が消えて何が残るかを画面に出します。**種別ごとに'
  '「消し方」「いちばん古いもの」「消えるファイルの名前と大きさ」'
  '「残すものとその理由」を書き、押すと**まとめて1回だけ**確認します。'
