  'ツールバーの「色 N列 ✕」からまとめて外せます。',
  '**ロールマスタを新設しました。**'
  'マスタ管理 > ロール で、設備ごとにロールの諸元'
  '（入出位置・接触面・ロール径MAX/MIN・面長・材質・硬度・本数・'
