  '**印刷プレビューのメニューを組み直しました。**'
  '「載せるもの／見せ方／用紙／刷り上がり」の4つに分け、'
  'いま効かない設定（分割の無い設備での子ロット、1日ぶんしか無いときの'
  '日付分け、全部の列が見えているときの「見える範囲だけ」など）は'
  '押せなくして理由をその場に出すようにしました。'
  '設定を既定へ戻すボタンも足しています。',
  '**一覧に「その場フィルタ」が付きました。**'
  'フィルタ枠の「その場フィルタ」を開き、カラムと条件を選んでおくと、'
