  '**欄の下／名前の横／出さない**を選べます（既定は欄の下）。',
  '**母材のときの「母材・丈は手入力です」を母材の見出しへ移しました。**'
  '上部帯のロット情報が見切れなくなります。',
  '**フラットネスの入力欄の見出しを1行に収めました。**'
  '〇／△／×はそのまま押せる札にまとめてあり、'
