  'これまでは「一覧へ移るときに前の画面を閉じる」処理を各画面が読み込み順に重ねて追加しており、ファイルを読み込む順番に依存する連鎖になっていました。6か所あったこの重ね掛けを廃止しています。',
  '作業スケジュールで仕掛一覧のポップアップを開いたときに、背後のスケジュール画面ごと閉じてしまう場合があったのを直しました。'
